 const my=Math.max(...bars,0),mn0=Math.min(...bars,0),{c,k,sx,sy}=frame(W,H,0,bars.length,mn0<0?mn0*1.15:0,my*1.15||1,title);k.textAlign='center';
 if(kind==='line'){k.strokeStyle=PAL[0];k.lineWidth=2.6;k.beginPath();bars.forEach((v,i)=>{const x=sx(i+.5),y=sy(v);i?k.lineTo(x,y):k.moveTo(x,y)});k.stroke();bars.forEach((v,i)=>dot(k,sx(i+.5),sy(v),PAL[0],bars.length<=12?fmt(v,4):'',W))}
 else bars.forEach((v,i)=>{k.fillStyle=PAL[kind==='hist'?0:i%PAL.length];const x=sx(i)+W/bars.length*.1,w=W/bars.length*.8;k.fillRect(x,Math.min(sy(v),sy(0)),w,Math.abs(sy(v)-sy(0)));k.fillStyle='#f5eff1';k.font='12px "JetBrains Mono",monospace';if(bars.length<=20)k.fillText(fmt(v,4),x+w/2,sy(v)-6)});
