 derivative:d=>{const a=nz(2,9),n=ri(2,5);let t,ans;if(d==1){t=poly([[a,n]])}else if(d==2){t=poly([[a,n],[nz(-9,9),1],[ri(-9,9),0]])}else t=pick([`sin(${a}x)·x^${n}`,`ln(x^2+${a})`,`e^(${a}x)·cos(x)`,`(x^2+${a})^${n}`]);
  const ast=parse(norm(t.replace(/·/g,'*')));ans=str(simp(diff(ast,'x')));return[`Differentiate f(x) = ${t}`,`f′(x) = ${ans}`]},
 integral:d=>{const cs=[[nz(1,6),ri(1,3)],[ri(-6,6),ri(0,2)]],lo=ri(0,2),hi=lo+ri(1,3);const F=x=>cs.reduce((s,[c,p])=>s+c*Math.pow(x,p+1)/(p+1),0),v=F(hi)-F(lo);return[`Evaluate ∫ from ${lo} to ${hi} of (${poly(cs)}) dx`,fmt(v)+(frac(v)?' (= '+frac(v)+')':'')]},
